const addDays = (date, n) => {
  const d = new Date(date);       // copy, do not mutate input
  d.setDate(d.getDate() + n);
  return d;
};
const start = new Date("2024-02-25T00:00:00Z");
console.log(addDays(start, 7).toISOString());

